# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
        return out
    return out

# region: render
def render(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: shape
def shape(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return shape(render(intake(gather(raw))))

